const delta=(now,prev,lowerIsBetter=true,unit='')=>{if(prev==null)return '';const d=now-prev;if(d===0)return `<span class="dl same">${ic('minus',13)}same as last week</span>`;const good=lowerIsBetter?d<0:d>0;return `<span class="dl ${good?'good':'bad'}">${ic(d>0?'arrow-up':'arrow-down',13)}${Math.abs(d)}${unit} vs last week</span>`;};
const neutral=(t)=>`<span class="dl same">${t}</span>`;
const weekNav=(label,sub,next=true)=>`<div class="row" style="gap:8px"><div class="nb">${ic('chevron-left',20)}</div><div style="flex:1;text-align:center"><div style="font-size:17px;font-weight:500">${label}</div>${sub?`<div class="muted" style="font-size:13px">${sub}</div>`:''}</div><div class="nb" ${next?'':'style="opacity:.35"'}>${ic('chevron-right',20)}</div></div>`;
const LOST=[['S','Speeding','3 times',7],['B','Hard braking','2 times',4],['A','Rapid acceleration','once',2],['P','Phone use','once',1]];
const scoreBlock=({n=86,prev=82,who='Sam',lost=LOST,dist='171 mi'}={})=>`<div class="row" style="gap:14px;align-items:flex-start"><div class="score big ${n<80?'mid':''}">${n}</div><div style="flex:1"><div style="font-size:16px;font-weight:500">Driving score</div><div class="muted" style="font-size:13.5px;line-height:1.4;margin-top:2px">From the Driving events in ${dist} checked this week. Fewer and milder events give a higher score.</div><div style="margin-top:6px">${prev==null?neutral('No drives last week to compare'):delta(n,prev,false)}</div></div></div>
<div class="lost">${lost.map(([k,t,c,p])=>`<div class="row" style="gap:10px;padding:6px 0"><div class="d" style="background:${EV[k][0]}">${ic(EV[k][1],15,'#fff',2.4)}</div><div style="flex:1;font-size:14.5px">${t} <span class="muted">· ${c}</span></div><b style="font-weight:500;font-size:14.5px">${p?'−'+p:'—'}</b></div>`).join('')}<div class="row" style="border-top:1px solid var(--olv);padding-top:7px;margin-top:3px;font-size:14.5px"><span class="sp">Starts at 100</span><b style="font-weight:600">${n}</b></div></div>`;
const STATS=[['11','drives',9,false,''],['187 mi','distance','up 22 mi'],['5 h 40','driving time','up 35 min'],['72 mph','top speed','down 3 mph']];
const statGrid=(s=STATS)=>`<div class="sg">${s.map(([v,l,c])=>`<div class="stat"><b>${v}</b><span>${l}</span>${c?`<div class="muted" style="font-size:12px;margin-top:3px">${c}</div>`:''}</div>`).join('')}</div>`;
const fixStats=()=>statGrid([['11','drives','2 more than last week'],['187 mi','distance','22 mi more'],['5 h 40','driving','35 min more'],['72 mph','top speed','3 mph lower']]);
const EVW=[['S','Speeding',3,5],['B','Hard braking',2,2],['A','Rapid acceleration',1,3],['P','Phone use',1,0]];
const evTable=(rows=EVW)=>`<div>${rows.map(([k,t,n,p])=>`<div class="ev" style="align-items:center"><div class="d" style="background:${EV[k][0]}">${ic(EV[k][1],17,'#fff',2.4)}</div><div style="flex:1"><b style="font-weight:500">${t}</b><small>${p==null?'':`${p} last week`}</small></div><div style="text-align:right"><b style="font-size:18px;font-weight:500">${n}</b><div>${p==null?'':delta(n,p)}</div></div></div>`).join('')}</div>`;
const checked=(a=9,b=11)=>`<div class="info">${ic('gauge',18)}<div><b style="font-weight:500;color:var(--on)">Speeding checked on ${a} of ${b} drives.</b> The other roads have no known speed limit, so they never count as speeding.</div></div>`;
const passLine=(n=2,d='14.6 mi')=>`<div class="item" style="border-radius:16px;min-height:56px"><div class="ic" style="border:2px dashed var(--drive);background:none">${ic('car',20)}</div><div class="t"><div style="font-weight:500">${n} Passenger drives · ${d}</div><small>Listed apart. They count towards nothing above.</small></div>${ic('chevron-right',20)}</div>`;
const days=[['M',2,92],['T',2,88],['W',1,95],['T',2,79],['F',3,84],['S',1,90],['S',0,null]];
const dayBars=(d=days,from=0)=>`<div class="row" style="align-items:flex-end;gap:8px;height:86px;padding:0 4px">${d.map(([l,n,s],i)=>`<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:4px;${i<from?'opacity:.3':''}"><div style="font-size:11px;color:var(--onv)">${n?s:''}</div><div style="width:100%;border-radius:6px;height:${n?n*18:3}px;background:${n?(s<80?'#E08A00':'#2E7D32'):'var(--olv)'}"></div><div style="font-size:12px;color:var(--onv)">${l}</div></div>`).join('')}</div><div class="muted" style="font-size:12px;margin:6px 4px 0">Drives each day, with that day's Driving score</div>`;
const seeAlso=(who)=>`<div class="info">${ic('eye',18)}<div>${who}</div></div>`;
const h=(t)=>`<div style="font-size:14px;font-weight:600;color:var(--p);margin:18px 0 8px">${t}</div>`;
const weekDrives=`<div class="grp">${[['Thu 19','17:38','Work → Home','23.1 mi · 44 min',72],['Fri 20','08:10','Home → Work','23.6 mi · 41 min',81],['Fri 20','13:02','Work → Costco','6.2 mi · 18 min',90]].map(([d,t,r,m,s])=>`<div class="item"><div style="width:48px;font-size:13px;font-weight:500;line-height:1.25">${d}<br><span class="muted" style="font-weight:400">${t}</span></div><div class="t"><div style="font-weight:500">${r}</div><small>${m}</small></div>${score(s)}</div>`).join('')}<div class="item" style="justify-content:center;color:var(--p);font-weight:500;min-height:48px">See all 11 drives</div></div>`;
const report=({own=false,bars=true,list=true}={})=>`
${scoreBlock()}
${h('Totals')}${fixStats()}
${bars?h('Day by day')+dayBars():''}
${h('Driving events')}${evTable()}
<div style="margin-top:10px">${checked()}</div>
${h('Not counted')}${passLine()}
${list?h('Drives')+weekDrives:''}
<div style="margin-top:14px">${seeAlso(own?'Family sees this report for the drives you share with them. Nobody is ranked against anyone else.':'Sam sees the same report. It only compares Sam with Sam’s own previous week.')}</div>`;
